package com.group01.assessment.application.usecase;
import com.group01.assessment.application.result.AttemptStructureResult; import com.group01.assessment.domain.exception.AssessmentNotFoundException; import com.group01.assessment.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class GetAttemptStructureUseCase { private final AssessmentAttemptRepository attempts; private final AttemptSectionRepository sections; private final AttemptItemRepository items; public GetAttemptStructureUseCase(AssessmentAttemptRepository attempts,AttemptSectionRepository sections,AttemptItemRepository items){this.attempts=attempts;this.sections=sections;this.items=items;} @Transactional(readOnly=true) public AttemptStructureResult execute(UUID userId,UUID attemptId){attempts.findByIdAndUserId(attemptId,userId).orElseThrow(()->new AssessmentNotFoundException("Assessment attempt not found")); var grouped=new HashMap<UUID,List<com.group01.assessment.domain.entity.AttemptItem>>(); items.findByAttemptId(attemptId).forEach(i->grouped.computeIfAbsent(i.attemptSectionId(),k->new ArrayList<>()).add(i)); var values=sections.findByAttemptId(attemptId).stream().map(s->new AttemptStructureResult.Section(s.id(),s.contentSectionId(),s.sortOrder(),s.snapshot(),grouped.getOrDefault(s.id(),List.of()).stream().map(i->new AttemptStructureResult.Item(i.id(),i.questionVersionId(),i.sortOrder(),i.questionSnapshot(),i.answerSnapshot(),i.knowledgeSnapshot())).toList())).toList(); return new AttemptStructureResult(values);} }
